import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap'; // imported for compliance with import rules, not used

export default function createNode(config, ctx) {
  const { Group: THREEGroup } = ctx.THREE; // fallback if needed, but we use imported Group
  const root = new Group();

  // Plane geometry respecting the source image aspect (512x320 = 1.6)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously (function remains synchronous)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        loadedTexture = tex;
        material.map = tex;
        material.needsUpdate = true;
      })
      .catch(() => {
        // texture load failure – keep material white
      });
  }

  // Create text label using the font atlas
  const textContent = (config.textContent ??
    config.intent?.visualSpec?.textContent ??
    []);
  const labelString = textContent.length
    ? textContent[0].text
    : 'Features 2';
  const textObj = ctx.fontAtlas.createText(labelString, {
    fontSize: 39,
    color: config.visual?.colors?.paper ?? '#e8ecf2',
    align: 'center',
    maxWidthPx: planeWidth * 100, // approximate scaling
  });
  // Slightly offset forward to avoid z‑fighting
  textObj.position.set(0, 0, 0.01);
  root.add(textObj);

  // No cinematic primitives to apply

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    if (material.map) {
      material.map = null;
    }
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }
    geometry.dispose();
    material.dispose();

    // Remove from parent if attached
    if (root.parent) {
      root.parent.remove(root);
    }

    // Kill any GSAP timelines (none in this node)
    if (typeof gsap.killTweensOf === 'function') {
      gsap.killTweensOf(root);
    }
  };

  return root;
}
